function BridgingAssessment({onDone}:{onDone:()=>void}){const [step,setStep]=useState(0);const steps:[string,string[]][]=[['Current position',['Independent Artist','Working Musician','Emerging Artist','Music Business Owner']],['Past experience & skills',['Live Performance','Songwriting','Recording','Touring','Promotion']],['Goals & challenges',['Book performances','Grow audience','Find collaborators','Secure funding','Build music business']],['Needs & next steps',['Booking','Promotion','Networking','Funding','Education','Creative services']]];return <section className="assessment-card"><div className="assessment-progress"><span style={{width:`${(step+1)*25}%`}}/></div><p className="mini-label">Step {step+1} of {steps.length}</p><h2>{steps[step][0]}</h2><p>Select the answers that best describe where you are today.</p><div className="choice-grid">{steps[step][1].map((x,i)=><button className={i<2?'selected':''} key={x}><span>{i<2&&<Check/>}</span>{x}</button>)}</div><label className="assessment-notes"><span>Add context</span><textarea placeholder="Tell MLI what matters most right now…"/></label><div className="assessment-actions"><button disabled={step===0} onClick={()=>setStep(Math.max(0,step-1))}>Back</button><button className="primary-action" onClick={()=>step===steps.length-1?onDone():setStep(step+1)}>{step===steps.length-1?'Save Bridging Summary':'Continue'} <ArrowRight/></button></div></section>}

