export function FastTrackPage(){
  const [checked,setChecked]=useState<Record<string,boolean>>({'review-bridging':true,'portfolio-proof':true,'connect-sarah':true});
  const [memberType,setMemberType]=useState('Artist / Musician');
  const [openWhy,setOpenWhy]=useState('');
  const [notice,setNotice]=useState('');
  const actionTotal=12, actionDone=Object.values(checked).filter(Boolean).length;
  const progress=Math.min(100,20+Math.max(0,actionDone-3)*5);
  const typeCopy=memberType==='Music Industry Professional'?'Build professional profile, join relevant groups, connect with clients, and offer services.':memberType==='Business / Venue / Organization'?'Complete your business profile, list opportunities, connect with artists, host events, and manage marketplace presence.':memberType==='Fan / Audiophile'?'Follow artists, join fan communities, discover live events, and support artists.':'Build profile, make booking connections, apply to performance opportunities, and attend industry events.';
  function toggleAction(action:FastTrackAction){setChecked(x=>{const next={...x,[action.id]:!x[action.id]};setNotice(!x[action.id]?`${action.title} marked complete. FastTrack progress updated.`:`${action.title} reopened.`);return next})}
  return <Shell><div className="fasttrack-screen"><div className="fasttrack-hero"><div><Badge gold>FastTrack</Badge><h1>A guided path from where you are now to where you want to go.</h1><p>Your Bridging profile becomes a personalized roadmap of milestones, recommendations, and next actions.</p><small>FastTrack adapts as your goals, activity, and progress change.</small><div className="current-goal"><span>YOUR CURRENT GOAL</span><b>Book more live performances and build stronger booking relationships.</b><p>Secondary goals: grow audience · improve promotion · build industry connections</p></div><div className="next-best-action"><div><Zap/><span>YOUR NEXT BEST ACTION</span><b>Add a live performance video.</b><p>This will strengthen your profile before you apply to showcases.</p></div><Link href="/profile/sarah-monroe">Add Media <ArrowRight/></Link></div></div><div className="track-orbit" role="progressbar" aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100} style={{background:`conic-gradient(#dab65c ${progress}%, #203a66 0)`}}><span>{progress}%</span><small>1 of 5 stages complete<br/>{actionDone} of {actionTotal} actions complete</small></div></div>{notice&&<p className="fasttrack-notice" role="status">{notice}<button onClick={()=>setNotice('')}>Dismiss</button></p>}<div className="fasttrack-member-context"><div><span className="mini-label">Member-type roadmap</span><h2>{memberType}</h2><p>{typeCopy}</p></div><div>{fastTrackMemberTypes.map(type=><button className={memberType===type?'active':''} onClick={()=>setMemberType(type)} key={type}>{type}</button>)}</div></div><div className="fasttrack-layout"><div><div className="milestone-row">{['Profile Ready','Network Activated','First Opportunity Application','First Industry Response','First Completed Opportunity'].map((m,i)=><article className={i<2?'done':i===2?'current':''} key={m}><small>MILESTONE {i+1}</small><b>{m}</b>{i<2&&<span><Check/> achieved</span>}{i===2&&<span>next</span>}</article>)}</div><div className="roadmap">{fastTrackSteps.map((step,i)=><FastTrackStepCard step={step} index={i} checked={checked} onToggle={toggleAction} openWhy={openWhy} setOpenWhy={setOpenWhy} key={step.title}/>)}</div></div><aside><WeeklyActions checked={checked} onToggle={toggleAction} openWhy={openWhy} setOpenWhy={setOpenWhy}/><ProgressSummary progress={progress} actionDone={actionDone}/></aside></div></div></Shell>
}
function FastTrackStepCard({step,index,checked,onToggle,openWhy,setOpenWhy}:{step:FastTrackStep;index:number;checked:Record<string,boolean>;onToggle:(action:FastTrackAction)=>void;openWhy:string;setOpenWhy:(id:string)=>void}){
  const percent=Math.round(step.doneCount/step.criteria.length*100);
  return <article className={`${step.status==='Complete'?'complete':step.status==='In progress'?'current':'locked'}`}><span>{step.status==='Complete'?<Check/>:index+1}</span><div><small>STEP {index+1}</small><h2>{step.title}</h2><p>{step.description}</p><div className="step-why"><Sparkles/> <b>Why this matters:</b> {step.why}</div><div className="micro-progress"><div><span>{step.doneCount} of {step.criteria.length} tasks complete</span><b>{percent}%</b></div><i><span style={{width:`${percent}%`}}/></i></div><div className="criteria-list">{step.criteria.map((item,i)=><p className={i<step.doneCount?'done':''} key={item}>{i<step.doneCount?<Check/>:<span/>}{item}</p>)}</div>{step.unlock&&<p className="unlock-note"><Crown size={14}/>{step.unlock}</p>}<div className="step-actions">{step.actions.map(action=><FastTrackActionRow action={action} done={Boolean(checked[action.id]||action.initialDone)} onToggle={()=>onToggle(action)} whyOpen={openWhy===action.id} onWhy={()=>setOpenWhy(openWhy===action.id?'':action.id)} key={action.id}/>)}</div>{index===2&&<PeopleRecommendations/>}{index===3&&<OpportunityRecommendations/>}</div><em>{step.status}</em></article>
}
function FastTrackActionRow({action,done,onToggle,whyOpen,onWhy}:{action:FastTrackAction;done:boolean;onToggle:()=>void;whyOpen:boolean;onWhy:()=>void}){
  return <div className={`fasttrack-action ${done?'done':''}`}><button aria-pressed={done} onClick={onToggle}>{done?<Check/>:<span/>}</button><div><div><Badge gold={action.priority==='High Priority'}>{action.category}</Badge>{action.priority&&<strong>{action.priority}</strong>}{action.timing&&<small>{action.timing}</small>}</div><b>{action.title}</b>{whyOpen&&<p>{action.why}</p>}<button onClick={onWhy}>Why this action?</button></div><Link href={action.href}>{action.cta}<ArrowRight size={13}/></Link></div>
}
function WeeklyActions({checked,onToggle,openWhy,setOpenWhy}:{checked:Record<string,boolean>;onToggle:(action:FastTrackAction)=>void;openWhy:string;setOpenWhy:(id:string)=>void}){
  const weekly=[fastTrackSteps[1].actions[0],fastTrackSteps[2].actions[0],fastTrackSteps[3].actions[0]];
  return <div className="panel fasttrack-week"><span className="mini-label">This Week</span><h3>3 actions to keep moving</h3><p>Recommended from your current FastTrack stage, Bridging profile, opportunity deadlines, and upcoming events.</p>{weekly.map(action=><FastTrackActionRow action={action} done={Boolean(checked[action.id])} onToggle={()=>onToggle(action)} whyOpen={openWhy===`week-${action.id}`} onWhy={()=>setOpenWhy(openWhy===`week-${action.id}`?'':`week-${action.id}`)} key={action.id}/>)}</div>
}
function PeopleRecommendations(){return <div className="fasttrack-recommendations"><h3>People You Should Meet</h3>{members.slice(0,3).map((m,i)=><article key={m.id}><Avatar initials={m.initials} tone={m.tone}/><p><b>{m.name}</b><small>{m.role} · {m.matchScore}% Match</small><span>{m.reason}</span></p><Link href={`/profile/${m.id}`}>View Profile</Link><ConnectionButton initial={i===0?'Request Sent':m.state}/></article>)}</div>}
function OpportunityRecommendations(){return <div className="fasttrack-recommendations opportunities"><h3>Recommended Opportunities</h3>{opportunities.slice(0,3).map(o=><article key={o.id}><span><BriefcaseBusiness/></span><p><b>{o.title}</b><small>{o.match}% Match · {o.deadline} · {o.compensation}</small><span>{o.reasons[0]}</span></p><Link href="/opportunities">{o.category==='Performance'?'Apply to Perform':'Apply'}</Link></article>)}</div>}
function ProgressSummary({progress,actionDone}:{progress:number;actionDone:number}){return <><div className="panel fasttrack-progress-summary"><span className="mini-label">Your Progress</span><h3>Actions completed: {actionDone} of 12</h3><div className="summary-meter"><span style={{width:`${progress}%`}}/></div>{[['Profile','80%'],['Connections Made','4'],['Opportunity Applications','3'],['Responses','1'],['Events Attended','2'],['Opportunities Completed','0']].map(([label,value])=><p key={label}><span>{label}</span><b>{value}</b></p>)}</div><div className="panel fasttrack-history"><span className="mini-label">Recent Progress</span><h3>Movement so far</h3>{['May 10 · Completed Bridging Profile','May 12 · Connected with Sarah Monroe','May 14 · Applied to CBS Studio Showcase','May 18 · Attended Networking Night'].map((x,i)=><p key={x} className={i<3?'complete':''}>{i<3?<Check/>:<Clock3/>}{x}</p>)}<div className="success-state-inline"><ShieldCheck/><b>First Connection Made</b><span>Sarah accepted your connection request.</span></div></div><div className="premium-panel fasttrack-pro-panel"><Crown/><h3>Unlock your full personalized roadmap.</h3><p>Get milestone tracking, recommended people, priority opportunities, and guided weekly actions.</p><Link href="/membership">Compare Memberships <ArrowRight/></Link><small>Preview your path. Unlock the full personalized roadmap with Pro.</small></div><div className="panel path-summary"><span className="mini-label">Your Path Summary</span>{[['Primary Goal','Book more live performances'],['Current Stage','Build Professional Presence'],['Next Milestone','Profile Ready'],['Next Best Action','Add performance media']].map(([k,v])=><p key={k}><span>{k}</span><b>{v}</b></p>)}<Link href="/bridging">Review Bridging Profile <ArrowRight size={14}/></Link></div></>}

